def evaluate_forecast(
    case,
    forecast,
    *,
    check_dependence=False,
    dependence_seed=0,
    n_calibration=99,
    alpha=0.05,
):
    """Validate a forecast and record scores without inventing pass thresholds.

    Malformed forecasts are rejected before scoring. Missing point, quantile,
    or ensemble outputs are UNSUPPORTED, not reconstructed from other output
    types. A known-mean discrepancy and one-path interval coverage are
    descriptive evidence and are INCONCLUSIVE as capability decisions.
    """
    manifest = dict(case.manifest)
    result = CaseResult(
        str(manifest.get("kind", manifest.get("scenario", "unknown"))),
        manifest.get("seed"),
        manifest=manifest,
    )
    try:
        violations = forecast.validate(case.task)
    except Exception as exc:
        result.diagnostics.append(
            DiagnosticResult(
                "forecast_contract",
                "ERROR",
                "correctness",
                "Forecast contract validation raised an exception.",
                exception_evidence(exc),
            )
        )
        return result
    if violations:
        result.diagnostics.extend(
            DiagnosticResult(
                "contract_" + str(item["code"]),
                "FAIL",
                "correctness",
                str(item["message"]),
                {"code": item["code"]},
            )
            for item in violations
        )
        return result
    result.diagnostics.append(
        DiagnosticResult(
            "forecast_contract",
            "PASS",
            "correctness",
            "Forecast indices, target order, shapes, finiteness, and quantile order satisfy the declared contract.",
        )
    )

    def score(name, function, *args):
        try:
            value = function(*args)
            if not np.isfinite(value):
                raise ValueError("score calculation returned a nonfinite value")
            result.metrics[name] = float(value)
        except metrics.UndefinedMetricError as exc:
            result.diagnostics.append(
                DiagnosticResult(
                    "metric_" + name,
                    "INCONCLUSIVE",
                    "capability",
                    str(exc),
                    {"reason": "undefined_metric"},
                )
            )
        except Exception as exc:
            result.diagnostics.append(
                DiagnosticResult(
                    "metric_" + name,
                    "ERROR",
                    "evaluation",
                    "Score calculation raised an exception.",
                    exception_evidence(exc),
                )
            )

    try:
        observed = metrics._array(case.observed.to_numpy(), "observed")
        expected_shape = (len(case.task.future_index), len(case.task.target_names))
        if observed.shape != expected_shape or not np.isfinite(observed).all():
            raise ValueError(
                "held-out observations must be finite and match the forecast task"
            )
        if (
            not case.observed.index.equals(case.task.future_index)
            or tuple(case.observed.columns) != case.task.target_names
        ):
            raise ValueError(
                "held-out observations must have the requested index and target order"
            )
    except Exception as exc:
        result.diagnostics.append(
            DiagnosticResult(
                "evaluation_data",
                "ERROR",
                "evaluation",
                "Held-out data do not satisfy the evaluation contract.",
                exception_evidence(exc),
            )
        )
        return result

    if case.reference is not None:
        try:
            reference = case.reference
            if (
                not reference.index.equals(case.task.future_index)
                or tuple(reference.target_names) != case.task.target_names
            ):
                raise ValueError(
                    "reference index and target order must match the forecast task"
                )
            reference_mean = metrics._array(reference.mean, "reference mean")
            reference_variance = metrics._array(
                reference.variance, "reference variance"
            )
            reference_covariance = metrics._array(
                reference.covariance, "reference covariance"
            )
            coordinates = int(np.prod(expected_shape))
            if (
                reference_mean.shape != expected_shape
                or reference_variance.shape != expected_shape
                or reference_covariance.shape != (coordinates, coordinates)
            ):
                raise ValueError(
                    "reference mean, variance, and covariance shapes must match the forecast task"
                )
            if not all(
                np.isfinite(value).all()
                for value in (reference_mean, reference_variance, reference_covariance)
            ):
                raise ValueError("reference parameters must be finite")
            if (
                np.any(reference_variance < 0)
                or not np.allclose(reference_covariance, reference_covariance.T)
                or not np.allclose(
                    np.diag(reference_covariance).reshape(expected_shape),
                    reference_variance,
                )
                or np.linalg.eigvalsh(reference_covariance).min() < -1e-10
            ):
                raise ValueError(
                    "reference covariance must be positive semidefinite and agree with its variances"
                )
        except Exception as exc:
            result.diagnostics.append(
                DiagnosticResult(
                    "evaluation_reference",
                    "ERROR",
                    "evaluation",
                    "Reference does not satisfy the evaluation contract.",
                    exception_evidence(exc),
                )
            )
            return result

    if forecast.point is None:
        result.diagnostics.append(
            DiagnosticResult(
                "point_accuracy",
                "UNSUPPORTED",
                "capability",
                "No explicit point forecast was supplied.",
            )
        )
    else:
        score("mse", metrics.mse, observed, forecast.point)
        score("mae", metrics.mae, observed, forecast.point)
        score(
            "mase", metrics.mase, observed, forecast.point, case.task.context.to_numpy()
        )
        if case.reference is not None:
            score(
                "mean_reference_mse",
                metrics.mean_reference_mse,
                case.reference.mean,
                forecast.point,
            )
        evidence = {
            name: value
            for name, value in result.metrics.items()
            if name in {"mse", "mae", "mase", "mean_reference_mse"}
        }
        if isinstance(case.reference, SimulationReference):
            evidence["reference"] = {
                "kind": case.reference.kind,
                **case.reference.capabilities,
            }
        result.diagnostics.append(
            DiagnosticResult(
                "point_accuracy",
                "INCONCLUSIVE",
                "capability",
                "Point scores are descriptive; no capability acceptance tolerance was declared.",
                evidence,
            )
        )

    if forecast.quantiles is None:
        result.diagnostics.append(
            DiagnosticResult(
                "quantile_accuracy",
                "UNSUPPORTED",
                "capability",
                "No explicit quantile forecasts were supplied.",
            )
        )
    else:
        score("pinball", metrics.pinball, observed, forecast.quantiles, forecast.levels)
        result.diagnostics.append(
            DiagnosticResult(
                "quantile_accuracy",
                "INCONCLUSIVE",
                "capability",
                "Quantile loss is descriptive; no capability acceptance tolerance was declared.",
            )
        )
        if len(forecast.levels) >= 2:
            quantiles = metrics._array(forecast.quantiles, "quantiles")
            coverage = float(
                np.mean(
                    (observed >= quantiles[..., 0]) & (observed <= quantiles[..., -1])
                )
            )
            nominal = float(forecast.levels[-1] - forecast.levels[0])
            result.metrics.update(
                interval_coverage=coverage, interval_nominal_coverage=nominal
            )

            def interval_width():
                # Scale each nonnegative width contribution before summing so
                # a representable mean is not lost to an overflowing total.
                count = quantiles[..., 0].size
                with np.errstate(over="raise", invalid="raise"):
                    return float(
                        np.sum(quantiles[..., -1] / count - quantiles[..., 0] / count)
                    )

            score("interval_width", interval_width)
            evidence = {
                "observed_coverage": coverage,
                "nominal_coverage": nominal,
                "lower_level": float(forecast.levels[0]),
                "upper_level": float(forecast.levels[-1]),
            }
            if "interval_width" in result.metrics:
                evidence["mean_width"] = result.metrics["interval_width"]
            result.diagnostics.append(
                DiagnosticResult(
                    "interval_coverage",
                    "INCONCLUSIVE",
                    "uncertainty",
                    "One-path coverage across possibly dependent coordinates does not establish calibration.",
                    evidence,
                )
            )
        else:
            result.diagnostics.append(
                DiagnosticResult(
                    "interval_coverage",
                    "UNSUPPORTED",
                    "uncertainty",
                    "At least two explicit quantile levels are needed to form an interval.",
                )
            )

    if forecast.samples is None:
        result.diagnostics.append(
            DiagnosticResult(
                "sample_scores",
                "UNSUPPORTED",
                "capability",
                "No joint predictive samples were supplied.",
            )
        )
    else:
        score("crps", metrics.crps, observed, forecast.samples)
        score("energy_score", metrics.energy_score, observed, forecast.samples)
        score("variogram_score", metrics.variogram_score, observed, forecast.samples)
        result.diagnostics.append(
            DiagnosticResult(
                "sample_scores",
                "INCONCLUSIVE",
                "capability",
                "Empirical marginal and joint scores are descriptive; no capability acceptance tolerance was declared.",
            )
        )

    if check_dependence:
        try:
            result.diagnostics.append(
                covariance_dependence_check(
                    case.reference,
                    forecast.samples,
                    seed=dependence_seed,
                    n_calibration=n_calibration,
                    alpha=alpha,
                )
            )
        except Exception as exc:
            result.diagnostics.append(
                DiagnosticResult(
                    "reference_covariance",
                    "ERROR",
                    "evaluation",
                    "Covariance comparison raised an exception.",
                    exception_evidence(exc),
                )
            )
    return result
